package com.mason.divinepotiontimer;

import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.geom.Arc2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Rectangle2D;
import java.awt.image.BufferedImage;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Function;
import javax.inject.Inject;
import net.runelite.api.ItemComposition;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.util.AsyncBufferedImage;

class DivinePotionTimerOverlay extends WidgetItemOverlay
{
    private static final float DARK_BRIGHTNESS = 0.50f;

    private final DivinePotionTimerPlugin plugin;
    private final DivinePotionTimerConfig config;
    private final ItemManager itemManager;
    private final Map<Integer, BufferedImage> darkenedImages = new ConcurrentHashMap<>();
    private final Map<Integer, BufferedImage> whiteOutlineImages = new ConcurrentHashMap<>();
    private final Set<Integer> requestedImages = ConcurrentHashMap.newKeySet();
    private final Set<Integer> requestedWhiteOutlineImages = ConcurrentHashMap.newKeySet();

    @Inject
    private DivinePotionTimerOverlay(
        DivinePotionTimerPlugin plugin,
        DivinePotionTimerConfig config,
        ItemManager itemManager)
    {
        this.plugin = plugin;
        this.config = config;
        this.itemManager = itemManager;

        showOnInventory();
        setPriority(PRIORITY_HIGH);
    }

    @Override
    public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
    {
        ItemComposition itemComposition = itemManager.getItemComposition(itemId);
        if (itemComposition == null)
        {
            return;
        }

        Rectangle bounds = widgetItem.getCanvasBounds();
        if (bounds == null)
        {
            return;
        }

        final long now = System.currentTimeMillis();
        DivinePotion divinePotion = DivinePotion.fromItemName(itemComposition.getName());
        if (divinePotion != null)
        {
            renderDivinePotion(graphics, itemId, bounds, divinePotion, now);
            return;
        }

        InventoryBuff inventoryBuff = InventoryBuff.fromItemName(itemComposition.getName());
        if (inventoryBuff != null)
        {
            renderInventoryBuff(graphics, itemId, bounds, inventoryBuff, now);
        }
    }

    private void renderDivinePotion(Graphics2D graphics, int itemId, Rectangle bounds,
        DivinePotion potion, long now)
    {
        boolean enabled = config.showDivineTimer();
        PotionTimer timer = plugin.getTimer(potion);
        boolean active = enabled && timer != null && timer.isActive(now);
        int secondsRemaining = active ? timer.getSecondsRemaining(now) : 0;

        // Test options deliberately remain usable even when the live divine
        // display is disabled. The near-expiration test only pulses the icon;
        // only Test Potion Timer creates a simulated countdown and indicators.
        boolean testTimer = config.testTimerDisplay();
        TestTimerPreview testPreview = plugin.getTestPotionTimerPreview(testTimer, now);
        if (testPreview != null)
        {
            secondsRemaining = testPreview.getSecondsRemaining();
        }

        boolean testBlink = config.testBlinkingAnimation();
        boolean blinkWindowReached = config.blinkStartSeconds() > 0
            && (active || testTimer)
            && secondsRemaining <= config.blinkStartSeconds();
        boolean pulse = testBlink || blinkWindowReached;
        boolean expiredOutline = enabled && !active && timer != null
            && timer.isWithinResetDelay(now, config.darkIconResetDelay());
        boolean showExpiredOutline = config.testExpiredPotion() || expiredOutline;

        drawInactiveIconState(graphics, itemId, bounds, now, showExpiredOutline, pulse);

        boolean displayTimer = (enabled && active) || testTimer;
        if (displayTimer)
        {
            double remainingFraction = testPreview != null
                ? testPreview.getRemainingFraction()
                : timer.getRemainingFraction(now);
            drawTimerDisplay(graphics, bounds, secondsRemaining, remainingFraction, config.timerTextColor());
        }
    }

    private void renderInventoryBuff(Graphics2D graphics, int itemId, Rectangle bounds,
        InventoryBuff buff, long now)
    {
        boolean enabled = isBuffDisplayEnabled(buff);
        boolean itemTestEnabled = buff == InventoryBuff.ANTIVENOM && config.testAntivenomTimer();

        // The shared Potion Timer test previews every recognized item family,
        // even when that family's live display is disabled. The near-expiration
        // test is intentionally separate and only pulses the icon without
        // creating a simulated timer or timer indicators.
        itemTestEnabled = itemTestEnabled || config.testTimerDisplay();

        boolean testExpiredPotion = config.testExpiredPotion();
        if (!enabled && !itemTestEnabled && !testExpiredPotion && !config.testBlinkingAnimation())
        {
            return;
        }

        if (buff == InventoryBuff.ANTIVENOM)
        {
            renderAntivenomItem(graphics, itemId, bounds, now);
            return;
        }

        PotionTimer timer = plugin.getTimer(buff);
        TestTimerPreview testPreview = plugin.getTestPotionTimerPreview(itemTestEnabled, now);
        boolean active = testPreview != null || (timer != null && timer.isActive(now));
        int secondsRemaining = testPreview != null
            ? testPreview.getSecondsRemaining()
            : (active ? timer.getSecondsRemaining(now) : 0);
        double remainingFraction = testPreview != null
            ? testPreview.getRemainingFraction()
            : (active && timer != null ? timer.getRemainingFraction(now) : 0.0);
        boolean pulse = config.testBlinkingAnimation()
            || (active && config.blinkStartSeconds() > 0
                && secondsRemaining <= config.blinkStartSeconds());

        // Anti-venom replaces the poison-protection state with its venom phase.
        // Do not darken ordinary antipoison bottles while that phase is active.
        TestTimerPreview testAntivenom = plugin.getTestAntivenomPreview(config.testAntivenomTimer(), now);
        PotionTimer antivenomTimer = plugin.getTimer(InventoryBuff.ANTIVENOM);
        boolean protectedByAntivenom = buff == InventoryBuff.ANTIPOISON
            && ((antivenomTimer != null && antivenomTimer.isActive(now))
                || (testAntivenom != null && testAntivenom.isVenomPhase()));
        boolean expiredOutline = enabled && !active && !protectedByAntivenom && timer != null
            && timer.isWithinResetDelay(now, config.darkIconResetDelay());
        boolean showExpiredOutline = testExpiredPotion || expiredOutline;

        drawInactiveIconState(graphics, itemId, bounds, now, showExpiredOutline, pulse);

        if (active && (enabled || itemTestEnabled))
        {
            drawTimerDisplay(graphics, bounds, secondsRemaining, remainingFraction, config.timerTextColor());
        }
    }

    private boolean isBuffDisplayEnabled(InventoryBuff buff)
    {
        switch (buff)
        {
            case ANTIPOISON:
                return config.showAntipoisonTimer();
            case ANTIVENOM:
                return config.showAntivenomTimer();
            case IMBUED_HEART:
                return config.showImbuedHeartTimer();
            case SMELLING_SALTS:
                return config.showSmellingSalts();
            case PRAYER_ENHANCE:
                return config.showPrayerEnhance();
            case OVERLOAD:
                return config.showOverloads();
            case PRAYER_REGENERATION:
                return config.showPrayerRegeneration();
            case STAMINA:
                return config.showStaminaPotion();
            case ANTIFIRE:
            case SUPER_ANTIFIRE:
                return config.showAntifirePotions();
            case GOADING_POTION:
                return config.showGoadingPotion();
            case MENAPHITE_REMEDY:
                return config.showMenaphiteRemedy();
            case LIQUID_ADRENALINE:
                return config.showLiquidAdrenaline();
            case SURGE_POTION:
                return config.showSurgePotion();
            case MOONLIGHT_POTION:
                return config.showMoonlightPotion();
            default:
                return false;
        }
    }

    private void renderAntivenomItem(Graphics2D graphics, int itemId, Rectangle bounds, long now)
    {
        boolean testEnabled = config.testAntivenomTimer();
        boolean testPotionTimer = config.testTimerDisplay();
        boolean testNearExpiration = config.testBlinkingAnimation();
        boolean testExpiredPotion = config.testExpiredPotion();
        if (!config.showAntivenomTimer() && !testEnabled && !testPotionTimer
            && !testNearExpiration && !testExpiredPotion)
        {
            return;
        }

        TestTimerPreview testPreview = plugin.getTestAntivenomPreview(testEnabled, now);
        // Do not include testNearExpiration here: that Debug option previews
        // only the blinking icon state, never a simulated countdown or pie/bar.
        TestTimerPreview generalTestPreview = testPreview == null
            ? plugin.getTestPotionTimerPreview(testPotionTimer, now)
            : null;
        PotionTimer venomTimer = plugin.getTimer(InventoryBuff.ANTIVENOM);
        PotionTimer poisonTimer = plugin.getTimer(InventoryBuff.ANTIPOISON);
        boolean venomActive = testPreview != null
            ? testPreview.isVenomPhase()
            : (generalTestPreview == null && venomTimer != null && venomTimer.isActive(now));
        boolean poisonActive = testPreview != null
            ? !testPreview.isVenomPhase()
            : (generalTestPreview != null || (poisonTimer != null && poisonTimer.isActive(now)));
        boolean effectActive = testPreview != null || generalTestPreview != null || venomActive || poisonActive;

        // The game exposes one poison-protection value with two sequential
        // phases. The test preview follows the same display transition.
        boolean displayTimer = false;
        int secondsRemaining = 0;
        double remainingFraction = 0.0;
        Color timerColor = config.timerTextColor();
        if (testPreview != null)
        {
            displayTimer = true;
            secondsRemaining = testPreview.getSecondsRemaining();
            remainingFraction = testPreview.getRemainingFraction();
            if (config.showAntivenomPhaseTimer() && testPreview.isVenomPhase())
            {
                timerColor = config.useCustomColorForVenom()
                    ? config.venomTimerTextColor()
                    : config.timerTextColor();
            }
            else if (!config.showAntivenomPhaseTimer())
            {
                // The test cycle uses a 60-second venom phase followed by
                // 120 seconds of poison protection.
                if (testPreview.isVenomPhase())
                {
                    secondsRemaining += 120;
                }
                remainingFraction = Math.min(1.0, secondsRemaining / 180.0);
            }
        }
        else if (generalTestPreview != null)
        {
            displayTimer = true;
            secondsRemaining = generalTestPreview.getSecondsRemaining();
            remainingFraction = generalTestPreview.getRemainingFraction();
        }
        else
        {
            PotionTimer displayTimerSource;
            if (!config.showAntivenomPhaseTimer())
            {
                displayTimerSource = plugin.getCombinedAntivenomTimer();
            }
            else if (venomActive)
            {
                displayTimerSource = venomTimer;
                timerColor = config.useCustomColorForVenom()
                    ? config.venomTimerTextColor()
                    : config.timerTextColor();
            }
            else
            {
                displayTimerSource = poisonActive ? poisonTimer : null;
            }

            if (displayTimerSource != null && displayTimerSource.isActive(now))
            {
                displayTimer = true;
                secondsRemaining = displayTimerSource.getSecondsRemaining(now);
                remainingFraction = displayTimerSource.getRemainingFraction(now);
            }
        }

        boolean pulse = testNearExpiration
            || (displayTimer && config.blinkStartSeconds() > 0
                && secondsRemaining <= config.blinkStartSeconds());

        PotionTimer resetTimer = !config.showAntivenomPhaseTimer()
            ? plugin.getCombinedAntivenomTimer()
            : (poisonTimer != null ? poisonTimer : venomTimer);
        boolean expiredOutline = !effectActive && resetTimer != null
            && resetTimer.isWithinResetDelay(now, config.darkIconResetDelay());
        boolean showExpiredOutline = testExpiredPotion || expiredOutline;
        drawInactiveIconState(graphics, itemId, bounds, now, showExpiredOutline, pulse);

        if (displayTimer && (config.showAntivenomTimer() || testEnabled || generalTestPreview != null))
        {
            drawTimerDisplay(graphics, bounds, secondsRemaining, remainingFraction, timerColor);
        }
        // If the venom-phase display is disabled, venom immunity remains active
        // but its text and visual timer are hidden.
    }

    /**
     * Near expiration, briefly darkens the original item sprite. Once the effect
     * expires, the sprite returns to its normal brightness and only its white
     * silhouette outline continues pulsing until the reset delay ends.
     */
    private void drawInactiveIconState(Graphics2D graphics, int itemId, Rectangle bounds,
        long now, boolean showExpiredOutline, boolean pulse)
    {
        if (showExpiredOutline)
        {
            drawWhiteBlinkingOutline(graphics, itemId, bounds, now);
            return;
        }

        if (pulse)
        {
            // Fade the 50%-brightness sprite over the original icon. Its alpha
            // mask preserves the potion silhouette and leaves the inventory slot untouched.
            drawBlinkingImage(graphics, itemId, bounds, now);
        }
    }

    private void drawTimerDisplay(Graphics2D graphics, Rectangle bounds, int seconds,
        double fraction, Color textColor)
    {
        drawTimerIndicators(graphics, bounds, fraction);
        if (config.showTimer())
        {
            drawTimer(
                graphics,
                bounds,
                formatTime(seconds),
                config.timerFontSize(),
                config.timerFont(),
                textColor);
        }
    }

    private void drawTimerIndicators(Graphics2D graphics, Rectangle bounds, double remainingFraction)
    {
        float overallOpacity = Math.max(0, Math.min(100, config.timerVisualOpacity())) / 100.0f;
        if (overallOpacity <= 0.0f)
        {
            return;
        }

        Graphics2D overlayGraphics = (Graphics2D) graphics.create();
        try
        {
            overlayGraphics.setComposite(
                AlphaComposite.getInstance(AlphaComposite.SRC_OVER, overallOpacity));

            if (config.pieChartSize() != TimerPieChartSize.NONE)
            {
                drawPieTimer(
                    overlayGraphics,
                    bounds,
                    remainingFraction,
                    config.timerBarColor(),
                    config.timerBackgroundColor(),
                    config.timerBackgroundOpacity(),
                    config.pieChartSize(),
                    config.borderColor(),
                    config.borderWidth());
            }

            drawBarTimer(
                overlayGraphics,
                bounds,
                remainingFraction,
                config.timerBarColor(),
                config.timerBackgroundColor(),
                config.timerBackgroundOpacity(),
                config.barTimerStyle(),
                config.barWidth(),
                config.borderColor(),
                config.borderWidth());
        }
        finally
        {
            overlayGraphics.dispose();
        }
    }

    /** Draws a countdown bar along the right or bottom edge of an inventory item. */
    private static void drawBarTimer(
        Graphics2D graphics,
        Rectangle bounds,
        double fractionRemaining,
        Color fillColor,
        Color backgroundColor,
        int backgroundOpacity,
        TimerBarStyle barStyle,
        int configuredThickness,
        Color borderColor,
        int configuredBorderWidth)
    {
        if (barStyle == null || barStyle == TimerBarStyle.NONE
            || bounds.width < 8 || bounds.height < 8)
        {
            return;
        }

        double remainingFraction = Math.max(0, Math.min(1, fractionRemaining));
        int barThickness = Math.max(1, Math.min(12, configuredThickness));
        boolean verticalBar = barStyle == TimerBarStyle.VERTICAL;

        int barWidth = verticalBar
            ? Math.min(barThickness, bounds.width - 4)
            : Math.max(4, bounds.width - 4);
        int barHeight = verticalBar
            ? Math.max(4, bounds.height - 4)
            : Math.min(barThickness, bounds.height - 4);
        int barX = verticalBar ? bounds.x + bounds.width - barWidth - 1 : bounds.x + 2;
        int barY = verticalBar ? bounds.y + 2 : bounds.y + bounds.height - barHeight - 1;

        Graphics2D barGraphics = (Graphics2D) graphics.create();
        try
        {
            barGraphics.setColor(withAlpha(backgroundColor, opacityToAlpha(backgroundOpacity)));
            barGraphics.fillRect(barX, barY, barWidth, barHeight);

            int borderWidth = Math.max(0, Math.min(8, configuredBorderWidth));
            int fillInset = borderWidth > 0 && Math.min(barWidth, barHeight) >= 3 ? 1 : 0;
            int fillX = barX + fillInset;
            int fillY = barY + fillInset;
            int fillWidth = Math.max(1, barWidth - 2 * fillInset);
            int fillHeight = Math.max(1, barHeight - 2 * fillInset);

            barGraphics.setColor(withAlpha(fillColor, 235));
            int filledLength = (int) Math.round(
                (verticalBar ? fillHeight : fillWidth) * remainingFraction);
            if (filledLength > 0)
            {
                int filledY = verticalBar ? fillY + fillHeight - filledLength : fillY;
                int filledWidth = verticalBar ? fillWidth : filledLength;
                int filledHeight = verticalBar ? filledLength : fillHeight;
                barGraphics.fillRect(fillX, filledY, filledWidth, filledHeight);
            }

            if (borderWidth > 0)
            {
                float strokeWidth = Math.min(
                    borderWidth,
                    Math.max(1, Math.min(barWidth, barHeight) - 1));
                barGraphics.setStroke(new BasicStroke(strokeWidth));
                barGraphics.setColor(withAlpha(borderColor, 255));
                barGraphics.draw(new Rectangle2D.Float(
                    barX + strokeWidth / 2,
                    barY + strokeWidth / 2,
                    Math.max(0, barWidth - strokeWidth),
                    Math.max(0, barHeight - strokeWidth)));
            }
        }
        finally
        {
            barGraphics.dispose();
        }
    }

    /** Draws a pie countdown in the selected size and position. */
    private static void drawPieTimer(
        Graphics2D graphics,
        Rectangle bounds,
        double fractionRemaining,
        Color fillColor,
        Color backgroundColor,
        int backgroundOpacity,
        TimerPieChartSize sizeMode,
        Color borderColor,
        int configuredBorderWidth)
    {
        if (sizeMode == TimerPieChartSize.NONE)
        {
            return;
        }

        double remainingFraction = Math.max(0, Math.min(1, fractionRemaining));
        int minimumItemDimension = Math.min(bounds.width, bounds.height);
        int pieSize = sizeMode == TimerPieChartSize.LARGE
            ? Math.max(18, Math.min(28, (int) Math.round(minimumItemDimension * 0.78)))
            : Math.max(9, Math.min(12, minimumItemDimension / 2));
        int pieX = sizeMode == TimerPieChartSize.LARGE
            ? bounds.x + (bounds.width - pieSize) / 2
            : bounds.x + bounds.width - pieSize - 1;
        int pieY = sizeMode == TimerPieChartSize.LARGE
            ? bounds.y + (bounds.height - pieSize) / 2
            : bounds.y + bounds.height - pieSize - 1;
        double arcBleed = 0.6;

        Graphics2D pieGraphics = (Graphics2D) graphics.create();
        try
        {
            pieGraphics.setColor(withAlpha(backgroundColor, opacityToAlpha(backgroundOpacity)));
            pieGraphics.fillOval(pieX, pieY, pieSize, pieSize);

            if (remainingFraction > 0)
            {
                int fillAlpha = sizeMode == TimerPieChartSize.LARGE ? 215 : 245;
                pieGraphics.setColor(withAlpha(fillColor, fillAlpha));
                pieGraphics.fill(new Arc2D.Double(
                    pieX - arcBleed,
                    pieY - arcBleed,
                    pieSize + 2 * arcBleed,
                    pieSize + 2 * arcBleed,
                    90,
                    -360 * remainingFraction,
                    Arc2D.PIE));
            }

            int borderWidth = Math.max(0, Math.min(8, configuredBorderWidth));
            if (borderWidth > 0)
            {
                float strokeWidth = Math.min(borderWidth, Math.max(1, pieSize - 1));
                double radius = pieSize / 2.0 + arcBleed + 0.5 - strokeWidth / 2.0;
                double centerX = pieX + pieSize / 2.0;
                double centerY = pieY + pieSize / 2.0;

                pieGraphics.setStroke(new BasicStroke(strokeWidth));
                pieGraphics.setColor(withAlpha(borderColor, 255));
                pieGraphics.draw(new Ellipse2D.Double(
                    centerX - radius,
                    centerY - radius,
                    2 * radius,
                    2 * radius));
            }
        }
        finally
        {
            pieGraphics.dispose();
        }
    }

    /** Converts a percentage setting into the 0-255 alpha range used by AWT. */
    private static int opacityToAlpha(int opacityPercent)
    {
        int clampedOpacity = Math.max(0, Math.min(100, opacityPercent));
        return (int) Math.round(clampedOpacity * 255.0 / 100.0);
    }

    private static Color withAlpha(Color color, int alpha)
    {
        return new Color(color.getRed(), color.getGreen(), color.getBlue(), alpha);
    }

    private void drawBlinkingImage(Graphics2D graphics, int itemId, Rectangle bounds, long now)
    {
        drawImage(graphics, getDarkenedImage(itemId), bounds, getBlinkOpacity(now));
    }

    private static float getBlinkOpacity(long now)
    {
        return (float) ((Math.sin(now % 1000L / 1000.0 * Math.PI * 2) + 1) * 0.5);
    }

    /** Draws an asynchronously cached sprite copy without changing the caller's graphics state. */
    private static void drawImage(Graphics2D graphics, BufferedImage image, Rectangle bounds, float opacity)
    {
        if (image == null || opacity <= 0)
        {
            return;
        }
        Graphics2D imageGraphics = (Graphics2D) graphics.create();
        try
        {
            imageGraphics.setComposite(
                AlphaComposite.getInstance(AlphaComposite.SRC_OVER, Math.min(1, opacity)));
            imageGraphics.drawImage(image, bounds.x, bounds.y, bounds.width, bounds.height, null);
        }
        finally
        {
            imageGraphics.dispose();
        }
    }

    private void drawWhiteBlinkingOutline(Graphics2D graphics, int itemId, Rectangle bounds, long now)
    {
        drawImage(graphics, getWhiteOutlineImage(itemId), bounds, 0.15f + getBlinkOpacity(now) * 0.85f);
    }

    private BufferedImage getWhiteOutlineImage(int itemId)
    {
        return getCachedImage(itemId, whiteOutlineImages, requestedWhiteOutlineImages,
            DivinePotionTimerOverlay::createWhiteOutlineImage);
    }

    private BufferedImage getDarkenedImage(int itemId)
    {
        return getCachedImage(itemId, darkenedImages, requestedImages,
            DivinePotionTimerOverlay::createDarkenedImage);
    }

    private BufferedImage getCachedImage(int itemId, Map<Integer, BufferedImage> cache,
        Set<Integer> requested, Function<BufferedImage, BufferedImage> transform)
    {
        BufferedImage cached = cache.get(itemId);
        if (cached != null || !requested.add(itemId))
        {
            return cached;
        }
        AsyncBufferedImage source = itemManager.getImage(itemId);
        if (source == null)
        {
            requested.remove(itemId);
            return null;
        }
        source.onLoaded(() -> {
            cache.put(itemId, transform.apply(source));
            requested.remove(itemId);
        });
        return null;
    }

    /**
     * Creates a soft white outer edge from the source sprite's alpha silhouette.
     * The first pixel ring is bright and the second ring creates a subtle glow.
     * Pixels belonging to the original sprite remain transparent in this image,
     * so the outline never washes out the potion artwork itself.
     */
    static BufferedImage createWhiteOutlineImage(BufferedImage source)
    {
        int width = source.getWidth();
        int height = source.getHeight();
        int[] pixels = source.getRGB(0, 0, width, height, null, 0, width);
        int[] outline = new int[pixels.length];
        for (int y = 0; y < height; y++)
        {
            for (int x = 0; x < width; x++)
            {
                if ((pixels[y * width + x] >>> 24) != 0)
                {
                    continue;
                }
                int nearest = Integer.MAX_VALUE;
                for (int dy = -2; dy <= 2; dy++)
                {
                    for (int dx = -2; dx <= 2; dx++)
                    {
                        int distanceSquared = dx * dx + dy * dy;
                        int sourceX = x + dx;
                        int sourceY = y + dy;
                        if (distanceSquared == 0 || distanceSquared > 4 || distanceSquared >= nearest
                            || sourceX < 0 || sourceX >= width
                            || sourceY < 0 || sourceY >= height)
                        {
                            continue;
                        }

                        if ((pixels[sourceY * width + sourceX] >>> 24) > 16)
                        {
                            nearest = distanceSquared;
                        }
                    }
                }
                int outlineAlpha;
                if (nearest <= 1)
                {
                    outlineAlpha = 245;
                }
                else if (nearest <= 2)
                {
                    outlineAlpha = 155;
                }
                else if (nearest <= 4)
                {
                    outlineAlpha = 75;
                }
                else
                {
                    outlineAlpha = 0;
                }

                if (outlineAlpha > 0)
                {
                    outline[y * width + x] = (outlineAlpha << 24) | 0x00FFFFFF;
                }
            }
        }
        BufferedImage result = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
        result.setRGB(0, 0, width, height, outline, 0, width);
        return result;
    }

    /**
     * Creates a darkened copy of the real item sprite. The original cached
     * RuneLite image is never modified and its per-pixel alpha is preserved.
     */
    static BufferedImage createDarkenedImage(BufferedImage source)
    {
        int width = source.getWidth();
        int height = source.getHeight();
        int[] pixels = source.getRGB(0, 0, width, height, null, 0, width);
        for (int i = 0; i < pixels.length; i++)
        {
            int argb = pixels[i];
            int alpha = argb >>> 24;
            if (alpha == 0)
            {
                continue;
            }

            int red = (int) (((argb >>> 16) & 0xFF) * DARK_BRIGHTNESS);
            int green = (int) (((argb >>> 8) & 0xFF) * DARK_BRIGHTNESS);
            int blue = (int) ((argb & 0xFF) * DARK_BRIGHTNESS);
            pixels[i] = (alpha << 24) | (red << 16) | (green << 8) | blue;
        }
        BufferedImage result = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
        result.setRGB(0, 0, width, height, pixels, 0, width);
        return result;
    }

    void clearImageCache()
    {
        darkenedImages.clear();
        whiteOutlineImages.clear();
        requestedImages.clear();
        requestedWhiteOutlineImages.clear();
    }

    private static void drawTimer(Graphics2D graphics, Rectangle bounds, String text,
        int fontSize, TimerFont timerFont, Color textColor)
    {
        Graphics2D textGraphics = (Graphics2D) graphics.create();
        try
        {
            Font font = timerFont.getFont().deriveFont((float) fontSize);
            textGraphics.setFont(font);
            textGraphics.setRenderingHint(
                RenderingHints.KEY_TEXT_ANTIALIASING,
                RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
            textGraphics.setRenderingHint(
                RenderingHints.KEY_FRACTIONALMETRICS,
                RenderingHints.VALUE_FRACTIONALMETRICS_OFF);

            int textWidth = textGraphics.getFontMetrics(font).stringWidth(text);
            int textX = bounds.x + (bounds.width - textWidth) / 2;
            int textY = bounds.y + bounds.height + 3;

            textGraphics.setComposite(AlphaComposite.SrcOver);
            textGraphics.setColor(new Color(0, 0, 0, 210));
            textGraphics.drawString(text, textX + 1, textY + 1);
            textGraphics.setColor(textColor);
            textGraphics.drawString(text, textX, textY);
        }
        finally
        {
            textGraphics.dispose();
        }
    }

    private static String formatTime(int seconds)
    {
        int minutes = seconds / 60;
        int secondsPart = seconds % 60;
        return minutes + ":" + (secondsPart < 10 ? "0" : "") + secondsPart;
    }
}

package com.mason.divinepotiontimer;

import com.google.inject.Provides;
import java.util.EnumMap;
import java.util.Locale;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
    name = "Potion Timer Overlay",
    description = "Displays countdown inventory overlays for potions, consumable buffs, poison protection and anti-venom effects.",
    tags = {"divine", "potion", "antipoison", "antivenom", "overload", "prayer", "salts", "timer", "inventory", "buff", "overlay"}
)
public class DivinePotionTimerPlugin extends Plugin
{
    @Inject
    private Client client;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private DivinePotionTimerOverlay overlay;

    private static final int POISON_TICK_LENGTH = 30;
    // Antivenom provides a venom-immunity phase followed by 38 poison ticks.
    private static final int ANTIVENOM_POISON_PHASE_TICKS = 38 * POISON_TICK_LENGTH;
    private static final int OVERLOAD_TICK_LENGTH = 25;
    private static final int ANTIFIRE_TICK_LENGTH = 30;
    private static final int SUPER_ANTIFIRE_TICK_LENGTH = 20;
    private static final long PRAYER_ENHANCE_DURATION_MILLIS = 290_000L;
    private static final long LIQUID_ADRENALINE_DURATION_MILLIS = 150_000L;

    private final Map<DivinePotion, PotionTimer> divinePotionTimers = new EnumMap<>(DivinePotion.class);
    private final Map<InventoryBuff, PotionTimer> inventoryBuffTimers = new EnumMap<>(InventoryBuff.class);
    private final PotionTimer combinedAntivenomTimer = new PotionTimer();
    private static final long TEST_ANTIVENOM_VENOM_PHASE_MILLIS = 60L * 1000L;
    private static final long TEST_ANTIVENOM_POISON_PHASE_MILLIS = 120L * 1000L;
    private static final long TEST_ANTIVENOM_CYCLE_MILLIS =
        TEST_ANTIVENOM_VENOM_PHASE_MILLIS + TEST_ANTIVENOM_POISON_PHASE_MILLIS;
    private static final long TEST_POTION_DURATION_MILLIS = 5 * 60_000L;

    private long testTimerExpiresAtMillis;
    private long testAntivenomCycleStartedAtMillis;
    private int nextPoisonTick = -1;
    private int nextOverloadRefreshTick = -1;
    private int activeOverloadVarbitId = -1;
    private int nextAntifireTick = -1;
    private int nextSuperAntifireTick = -1;

    @Provides
    DivinePotionTimerConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(DivinePotionTimerConfig.class);
    }

    @Override
    protected void startUp()
    {
        overlayManager.add(overlay);
        if (client.getGameState() == GameState.LOGGED_IN)
        {
            synchronizeTimersWithGame();
        }
    }

    @Override
    protected void shutDown()
    {
        overlayManager.remove(overlay);
        overlay.clearImageCache();
        resetSession();
    }

    private void resetSession()
    {
        divinePotionTimers.clear();
        inventoryBuffTimers.clear();
        combinedAntivenomTimer.updateFromRemainingTicks(0, System.currentTimeMillis());

        testTimerExpiresAtMillis = 0L;
        testAntivenomCycleStartedAtMillis = 0L;
        nextPoisonTick = -1;
        nextOverloadRefreshTick = -1;
        activeOverloadVarbitId = -1;
        nextAntifireTick = -1;
        nextSuperAntifireTick = -1;
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOGIN_SCREEN)
        {
            resetSession();
        }
        else if (event.getGameState() == GameState.LOGGED_IN)
        {
            synchronizeTimersWithGame();
        }
    }

    @Subscribe
    public void onVarbitChanged(VarbitChanged event)
    {
        int changedVarbitId = event.getVarbitId();
        int changedValue = event.getValue();
        long now = System.currentTimeMillis();

        if (DivinePotion.fromVarbit(changedVarbitId) != null)
        {
            // Read all eight values together. Some potions (for example,
            // super combat) also set the component stat varbits. The priority
            // checks below mirror RuneLite's own handling so one sip does not
            // create several duplicate timers for the same combined effect.
            synchronizeDivineTimers(changedVarbitId, changedValue);
        }

        if (changedVarbitId == VarbitID.IMBUED_HEART_TIMER)
        {
            updateInventoryBuffTimer(InventoryBuff.IMBUED_HEART,
                Math.max(0, changedValue) * 10, now);
        }

        if (event.getVarpId() == VarPlayerID.POISON)
        {
            updateAntipoisonTimer(changedValue, now);
        }

        if (changedVarbitId == VarbitID.TOA_MIDRAIDLOOT_STATS_TIMER)
        {
            updateInventoryBuffTimer(InventoryBuff.SMELLING_SALTS,
                Math.max(0, changedValue) * 25, now);
        }

        if (changedVarbitId == VarbitID.STATRENEWAL_POTION_TIMER)
        {
            updateInventoryBuffTimer(InventoryBuff.MENAPHITE_REMEDY,
                Math.max(0, changedValue) * 25, now);
        }

        if (changedVarbitId == VarbitID.PRAYER_REGENERATION_POTION_TIMER)
        {
            updateInventoryBuffTimer(InventoryBuff.PRAYER_REGENERATION,
                Math.max(0, changedValue) * 12, now);
        }

        if (changedVarbitId == VarbitID.GOADING_POTION_TIMER)
        {
            updateInventoryBuffTimer(InventoryBuff.GOADING_POTION,
                Math.max(0, changedValue) * 6, now);
        }

        if (changedVarbitId == VarbitID.NZONE_OVERLOAD_POTION_EFFECTS
            || changedVarbitId == VarbitID.RAIDS_OVERLOAD_TIMER
            || changedVarbitId == VarbitID.DEADMAN_OVERLOAD_POTION_EFFECTS
            || changedVarbitId == VarbitID.RAIDS_CLIENT_INDUNGEON)
        {
            updateOverloadTimer(changedVarbitId, changedValue, now);
        }

        if (changedVarbitId == VarbitID.STAMINA_ACTIVE || changedVarbitId == VarbitID.STAMINA_DURATION)
        {
            updateStaminaTimer(changedVarbitId, changedValue, now);
        }

        if (changedVarbitId == VarbitID.ANTIFIRE_POTION)
        {
            updateAntifireTimer(InventoryBuff.ANTIFIRE, changedValue,
                ANTIFIRE_TICK_LENGTH, false, now);
        }

        if (changedVarbitId == VarbitID.SUPER_ANTIFIRE_POTION)
        {
            updateAntifireTimer(InventoryBuff.SUPER_ANTIFIRE, changedValue,
                SUPER_ANTIFIRE_TICK_LENGTH, true, now);
        }

        if (changedVarbitId == VarbitID.TOA_MIDRAIDLOOT_ENERGY_ACTIVE)
        {
            updateInventoryBuffTimerDuration(InventoryBuff.LIQUID_ADRENALINE,
                changedValue > 0 ? LIQUID_ADRENALINE_DURATION_MILLIS : 0L, now);
        }

        if (changedVarbitId == VarbitID.SURGE_POTION_TIMER)
        {
            updateInventoryBuffTimer(InventoryBuff.SURGE_POTION,
                Math.max(0, changedValue) * 10, now);
        }

        if (changedVarbitId == VarbitID.MOONLIGHT_POTION_TIME)
        {
            int moonlightValue = changedValue;
            // RuneLite accounts for a one-tick desync when moonlight potion
            // and divine defence are active together.
            if (client.getVarbitValue(VarbitID.DIVINEDEFENCE_POTION_TIME) == moonlightValue + 1)
            {
                moonlightValue++;
            }
            updateInventoryBuffTimer(InventoryBuff.MOONLIGHT_POTION, Math.max(0, moonlightValue), now);
        }

        if (changedVarbitId == VarbitID.RAIDS_CLIENT_INDUNGEON && changedValue == 0)
        {
            // Prayer Enhance only exists in the raid. Leaving the raid ends its effect.
            updateInventoryBuffTimerDuration(InventoryBuff.PRAYER_ENHANCE, 0L, now);
        }
    }

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        String message = event.getMessage();
        if (message == null
            || (event.getType() != ChatMessageType.SPAM && event.getType() != ChatMessageType.GAMEMESSAGE))
        {
            return;
        }

        String normalized = message.toLowerCase(Locale.ROOT);
        long now = System.currentTimeMillis();
        if (message.startsWith("You drink some of your") && normalized.contains("prayer enhance"))
        {
            // RuneLite's Timers & Buffs plugin uses the same game message and
            // a fixed 290-second duration for Prayer Enhance.
            updateInventoryBuffTimerDuration(InventoryBuff.PRAYER_ENHANCE,
                PRAYER_ENHANCE_DURATION_MILLIS, now);
        }
        else if (normalized.contains("your prayer enhance effect has worn off"))
        {
            updateInventoryBuffTimerDuration(InventoryBuff.PRAYER_ENHANCE, 0L, now);
        }
        else if (normalized.contains("reducing the energy cost of your special attacks"))
        {
            // Liquid adrenaline has a 150-second duration. Its active varbit
            // clears the timer at expiration; this chat trigger also catches
            // the sip in case the corresponding varbit is already non-zero.
            updateInventoryBuffTimerDuration(InventoryBuff.LIQUID_ADRENALINE,
                LIQUID_ADRENALINE_DURATION_MILLIS, now);
        }
    }

    private void synchronizeTimersWithGame()
    {
        synchronizeDivineTimers(-1, 0);
        synchronizeInventoryBuffTimers();
    }

    private void synchronizeInventoryBuffTimers()
    {
        long now = System.currentTimeMillis();
        int heartRemaining = Math.max(0, client.getVarbitValue(VarbitID.IMBUED_HEART_TIMER));
        updateInventoryBuffTimer(InventoryBuff.IMBUED_HEART, heartRemaining * 10, now);
        updateAntipoisonTimer(client.getVarpValue(VarPlayerID.POISON), now);

        updateInventoryBuffTimer(InventoryBuff.SMELLING_SALTS,
            Math.max(0, client.getVarbitValue(VarbitID.TOA_MIDRAIDLOOT_STATS_TIMER)) * 25, now);
        updateInventoryBuffTimer(InventoryBuff.MENAPHITE_REMEDY,
            Math.max(0, client.getVarbitValue(VarbitID.STATRENEWAL_POTION_TIMER)) * 25, now);
        updateInventoryBuffTimer(InventoryBuff.PRAYER_REGENERATION,
            Math.max(0, client.getVarbitValue(VarbitID.PRAYER_REGENERATION_POTION_TIMER)) * 12, now);
        updateInventoryBuffTimer(InventoryBuff.GOADING_POTION,
            Math.max(0, client.getVarbitValue(VarbitID.GOADING_POTION_TIMER)) * 6, now);
        updateOverloadTimer(-1, 0, now);
        updateStaminaTimer(-1, 0, now);
        updateAntifireTimer(InventoryBuff.ANTIFIRE,
            client.getVarbitValue(VarbitID.ANTIFIRE_POTION), ANTIFIRE_TICK_LENGTH, false, now);
        updateAntifireTimer(InventoryBuff.SUPER_ANTIFIRE,
            client.getVarbitValue(VarbitID.SUPER_ANTIFIRE_POTION), SUPER_ANTIFIRE_TICK_LENGTH, true, now);
        updateInventoryBuffTimer(InventoryBuff.SURGE_POTION,
            Math.max(0, client.getVarbitValue(VarbitID.SURGE_POTION_TIMER)) * 10, now);

        int moonlightValue = client.getVarbitValue(VarbitID.MOONLIGHT_POTION_TIME);
        if (client.getVarbitValue(VarbitID.DIVINEDEFENCE_POTION_TIME) == moonlightValue + 1)
        {
            moonlightValue++;
        }
        updateInventoryBuffTimer(InventoryBuff.MOONLIGHT_POTION, Math.max(0, moonlightValue), now);
        // Prayer Enhance is chat-message timed, so it is intentionally not
        // reconstructed from a full 290 seconds when the plugin starts mid-effect.
        // Liquid adrenaline is a boolean varbit; only a new activation can give
        // us an accurate 150-second start time.
    }

    private void updateInventoryBuffTimerDuration(InventoryBuff buff, long remainingMillis, long now)
    {
        PotionTimer timer = inventoryBuffTimers.computeIfAbsent(buff, ignored -> new PotionTimer());
        timer.updateFromDurationMillis(remainingMillis, now);
    }

    private void updateStaminaTimer(int changedVarbitId, int changedValue, long now)
    {
        int staminaActive = readVarbit(VarbitID.STAMINA_ACTIVE, changedVarbitId, changedValue);
        int staminaDuration = readVarbit(VarbitID.STAMINA_DURATION, changedVarbitId, changedValue);
        int remainingTicks = staminaActive == 1 ? Math.max(0, staminaDuration) * 10 : 0;
        updateInventoryBuffTimer(InventoryBuff.STAMINA, remainingTicks, now);
    }

    private void updateAntifireTimer(InventoryBuff buff, int remainingUnits,
        int tickInterval, boolean superAntifire, long now)
    {
        int tickCount = client.getTickCount();
        int nextTick = superAntifire ? nextSuperAntifireTick : nextAntifireTick;
        if (remainingUnits <= 0)
        {
            nextTick = -1;
            updateInventoryBuffTimer(buff, 0, now);
        }
        else
        {
            if (nextTick - tickCount <= 0)
            {
                nextTick = tickCount + tickInterval;
            }
            int ticksRemaining = nextTick - tickCount + (remainingUnits - 1) * tickInterval;
            updateInventoryBuffTimer(buff, Math.max(0, ticksRemaining), now);
        }

        if (superAntifire)
        {
            nextSuperAntifireTick = nextTick;
        }
        else
        {
            nextAntifireTick = nextTick;
        }
    }

    private void updateOverloadTimer(int changedVarbitId, int changedValue, long now)
    {
        int deadmanRemaining = readVarbit(
            VarbitID.DEADMAN_OVERLOAD_POTION_EFFECTS, changedVarbitId, changedValue);
        int raidRemaining = readVarbit(
            VarbitID.RAIDS_OVERLOAD_TIMER, changedVarbitId, changedValue);
        int nightmareZoneRemaining = readVarbit(
            VarbitID.NZONE_OVERLOAD_POTION_EFFECTS, changedVarbitId, changedValue);
        boolean inRaid = changedVarbitId == VarbitID.RAIDS_CLIENT_INDUNGEON
            ? changedValue == 1
            : client.getVarbitValue(VarbitID.RAIDS_CLIENT_INDUNGEON) == 1;
        int selectedVarbit = -1;
        int remainingUnits = 0;

        if (deadmanRemaining > 0)
        {
            selectedVarbit = VarbitID.DEADMAN_OVERLOAD_POTION_EFFECTS;
            remainingUnits = deadmanRemaining;
        }
        else if ((inRaid || changedVarbitId == VarbitID.RAIDS_OVERLOAD_TIMER) && raidRemaining > 0)
        {
            // Accept the raid overload varbit's activation event even if the
            // in-dungeon flag is delivered a moment later.
            selectedVarbit = VarbitID.RAIDS_OVERLOAD_TIMER;
            remainingUnits = raidRemaining;
        }
        else if (nightmareZoneRemaining > 0)
        {
            selectedVarbit = VarbitID.NZONE_OVERLOAD_POTION_EFFECTS;
            remainingUnits = nightmareZoneRemaining;
        }

        if (remainingUnits <= 0)
        {
            nextOverloadRefreshTick = -1;
            activeOverloadVarbitId = -1;
            updateInventoryBuffTimer(InventoryBuff.OVERLOAD, 0, now);
            return;
        }

        int tickCount = client.getTickCount();
        if (selectedVarbit != activeOverloadVarbitId || nextOverloadRefreshTick - tickCount <= 0)
        {
            nextOverloadRefreshTick = tickCount + OVERLOAD_TICK_LENGTH;
            activeOverloadVarbitId = selectedVarbit;
        }

        int ticksRemaining = nextOverloadRefreshTick - tickCount
            + (remainingUnits - 1) * OVERLOAD_TICK_LENGTH;
        updateInventoryBuffTimer(InventoryBuff.OVERLOAD, Math.max(0, ticksRemaining), now);
    }

    private void synchronizeDivineTimers(int changedVarbitId, int changedValue)
    {
        final long now = System.currentTimeMillis();

        // Prefer the value carried by the event for the variable that just
        // changed. Read the other values from the client to resolve combined
        // divine effects against their current state.
        final int superAttackTicks = readVarbit(
            VarbitID.DIVINEATTACK_POTION_TIME, changedVarbitId, changedValue);
        final int superStrengthTicks = readVarbit(
            VarbitID.DIVINESTRENGTH_POTION_TIME, changedVarbitId, changedValue);
        final int superDefenceTicks = readVarbit(
            VarbitID.DIVINEDEFENCE_POTION_TIME, changedVarbitId, changedValue);
        final int rangingTicks = readVarbit(
            VarbitID.DIVINERANGE_POTION_TIME, changedVarbitId, changedValue);
        final int magicTicks = readVarbit(
            VarbitID.DIVINEMAGIC_POTION_TIME, changedVarbitId, changedValue);
        final int superCombatTicks = readVarbit(
            VarbitID.DIVINECOMBAT_POTION_TIME, changedVarbitId, changedValue);
        final int bastionTicks = readVarbit(
            VarbitID.DIVINEBASTION_POTION_TIME, changedVarbitId, changedValue);
        final int battlemageTicks = readVarbit(
            VarbitID.DIVINEBATTLEMAGE_POTION_TIME, changedVarbitId, changedValue);

        // Combined potions also update their component varbits. Compare the
        // current values so one sip produces only the correct inventory timer.
        updateTimer(DivinePotion.SUPER_ATTACK,
            superAttackTicks > 0 && superAttackTicks > superCombatTicks ? superAttackTicks : 0, now);
        updateTimer(DivinePotion.SUPER_STRENGTH,
            superStrengthTicks > 0 && superStrengthTicks > superCombatTicks ? superStrengthTicks : 0, now);
        updateTimer(DivinePotion.SUPER_DEFENCE,
            superDefenceTicks > 0
                && superDefenceTicks > superCombatTicks
                && superDefenceTicks > bastionTicks
                && superDefenceTicks > battlemageTicks
                ? superDefenceTicks : 0,
            now);
        updateTimer(DivinePotion.RANGING,
            rangingTicks > 0 && rangingTicks > bastionTicks ? rangingTicks : 0, now);
        updateTimer(DivinePotion.MAGIC,
            magicTicks > 0 && magicTicks > battlemageTicks ? magicTicks : 0, now);
        updateTimer(DivinePotion.SUPER_COMBAT, superCombatTicks, now);
        updateTimer(DivinePotion.BASTION, bastionTicks, now);
        updateTimer(DivinePotion.BATTLEMAGE, battlemageTicks, now);
    }

    private int readVarbit(int varbitId, int changedVarbitId, int changedValue)
    {
        if (varbitId == changedVarbitId)
        {
            return changedValue;
        }

        return client.getVarbitValue(varbitId);
    }

    private void updateTimer(DivinePotion potion, int remainingTicks, long now)
    {
        updateTimer(divinePotionTimers, potion, remainingTicks, now);
    }

    PotionTimer getTimer(DivinePotion potion)
    {
        return divinePotionTimers.get(potion);
    }

    PotionTimer getTimer(InventoryBuff buff)
    {
        return inventoryBuffTimers.get(buff);
    }

    PotionTimer getCombinedAntivenomTimer()
    {
        return combinedAntivenomTimer;
    }

    private void updateInventoryBuffTimer(InventoryBuff buff, int remainingTicks, long now)
    {
        updateTimer(inventoryBuffTimers, buff, remainingTicks, now);
    }

    private static <K> void updateTimer(
        Map<K, PotionTimer> timersByEffect,
        K effect,
        int remainingTicks,
        long now)
    {
        PotionTimer timer = timersByEffect.computeIfAbsent(effect, ignored -> new PotionTimer());
        timer.updateFromRemainingTicks(remainingTicks, now);
    }

    private void updateAntipoisonTimer(int poisonVarpValue, long now)
    {
        int tickCount = client.getTickCount();
        if (poisonVarpValue < 0)
        {
            if (nextPoisonTick - tickCount <= 0)
            {
                nextPoisonTick = tickCount + POISON_TICK_LENGTH;
            }

            int ticksUntilNextPoisonUpdate = nextPoisonTick - tickCount;
            int poisonTicksRemaining = 0;
            int venomTicksRemaining = 0;
            if (poisonVarpValue >= -38)
            {
                // The regular poison-immunity phase runs from -38 through -1.
                poisonTicksRemaining = ticksUntilNextPoisonUpdate
                    + Math.abs((poisonVarpValue + 1) * POISON_TICK_LENGTH);
                updateInventoryBuffTimer(InventoryBuff.ANTIPOISON,
                    Math.max(0, poisonTicksRemaining), now);
            }
            else
            {
                updateInventoryBuffTimer(InventoryBuff.ANTIPOISON, 0, now);
            }

            if (poisonVarpValue < -38)
            {
                // Values below -38 represent the separate venom-immunity phase.
                venomTicksRemaining = ticksUntilNextPoisonUpdate
                    + Math.abs((poisonVarpValue + 1 + 38) * POISON_TICK_LENGTH);
                updateInventoryBuffTimer(InventoryBuff.ANTIVENOM,
                    Math.max(0, venomTicksRemaining), now);
                // Include the full following poison-protection phase so this
                // timer counts down continuously across both phases.
                combinedAntivenomTimer.updateFromRemainingTicks(
                    Math.max(0, venomTicksRemaining + ANTIVENOM_POISON_PHASE_TICKS), now);
            }
            else
            {
                updateInventoryBuffTimer(InventoryBuff.ANTIVENOM, 0, now);
                combinedAntivenomTimer.updateFromRemainingTicks(Math.max(0, poisonTicksRemaining), now);
            }
        }
        else
        {
            nextPoisonTick = -1;
            updateInventoryBuffTimer(InventoryBuff.ANTIPOISON, 0, now);
            updateInventoryBuffTimer(InventoryBuff.ANTIVENOM, 0, now);
            combinedAntivenomTimer.updateFromRemainingTicks(0, now);
        }
    }

    /** A shared five-minute Potion Timer preview for every supported inventory item. */
    TestTimerPreview getTestPotionTimerPreview(boolean enabled, long nowMillis)
    {
        if (!enabled)
        {
            testTimerExpiresAtMillis = 0L;
            return null;
        }

        if (testTimerExpiresAtMillis <= nowMillis)
        {
            testTimerExpiresAtMillis = nowMillis + TEST_POTION_DURATION_MILLIS;
        }

        long remainingMillis = testTimerExpiresAtMillis - nowMillis;
        int secondsRemaining = (int) Math.max(1L, (remainingMillis + 999L) / 1000L);
        double remainingFraction = (double) remainingMillis / TEST_POTION_DURATION_MILLIS;
        return new TestTimerPreview(secondsRemaining, remainingFraction, false);
    }


    /**
     * Returns a repeating anti-venom preview: one minute of venom immunity
     * followed by two minutes of poison immunity. This makes the phase change
     * quick to test without consuming an in-game potion.
     */
    TestTimerPreview getTestAntivenomPreview(boolean enabled, long nowMillis)
    {
        if (!enabled)
        {
            testAntivenomCycleStartedAtMillis = 0L;
            return null;
        }

        if (testAntivenomCycleStartedAtMillis == 0L)
        {
            testAntivenomCycleStartedAtMillis = nowMillis;
        }

        long elapsed = Math.floorMod(nowMillis - testAntivenomCycleStartedAtMillis,
            TEST_ANTIVENOM_CYCLE_MILLIS);
        if (elapsed < TEST_ANTIVENOM_VENOM_PHASE_MILLIS)
        {
            long remaining = TEST_ANTIVENOM_VENOM_PHASE_MILLIS - elapsed;
            int seconds = (int) Math.max(1L, (remaining + 999L) / 1000L);
            return new TestTimerPreview(seconds,
                (double) remaining / TEST_ANTIVENOM_VENOM_PHASE_MILLIS, true);
        }

        long poisonElapsed = elapsed - TEST_ANTIVENOM_VENOM_PHASE_MILLIS;
        long remaining = TEST_ANTIVENOM_POISON_PHASE_MILLIS - poisonElapsed;
        int seconds = (int) Math.max(1L, (remaining + 999L) / 1000L);
        return new TestTimerPreview(seconds,
            (double) remaining / TEST_ANTIVENOM_POISON_PHASE_MILLIS, false);
    }
}

package com.mason.divinepotiontimer;

import java.util.Locale;
import java.util.regex.Pattern;

/** A consumable effect whose matching inventory items can display a timer. */
enum InventoryBuff
{
    ANTIPOISON,
    ANTIVENOM,
    IMBUED_HEART,
    SMELLING_SALTS,
    PRAYER_ENHANCE,
    OVERLOAD,
    PRAYER_REGENERATION,
    STAMINA,
    ANTIFIRE,
    SUPER_ANTIFIRE,
    GOADING_POTION,
    MENAPHITE_REMEDY,
    LIQUID_ADRENALINE,
    SURGE_POTION,
    MOONLIGHT_POTION;

    private static final Pattern DOSE_SUFFIX = Pattern.compile("\\s*\\(\\d+\\)$");

    /** Maps an inventory item's display name to the effect it represents. */
    static InventoryBuff fromItemName(String name)
    {
        if (name == null)
        {
            return null;
        }

        String normalizedName = DOSE_SUFFIX.matcher(name.trim().toLowerCase(Locale.ROOT))
            .replaceFirst("")
            .trim();

        if (normalizedName.startsWith("prayer enhance"))
        {
            return PRAYER_ENHANCE;
        }
        if (normalizedName.equals("smelling salts"))
        {
            return SMELLING_SALTS;
        }
        if (normalizedName.startsWith("overload") || normalizedName.startsWith("blighted overload"))
        {
            return OVERLOAD;
        }
        if (normalizedName.startsWith("prayer regeneration potion"))
        {
            return PRAYER_REGENERATION;
        }
        if (normalizedName.startsWith("extended stamina potion")
            || normalizedName.startsWith("stamina potion"))
        {
            return STAMINA;
        }
        if (normalizedName.startsWith("extended super antifire")
            || normalizedName.startsWith("super antifire"))
        {
            return SUPER_ANTIFIRE;
        }
        if (normalizedName.startsWith("extended antifire")
            || normalizedName.startsWith("antifire potion"))
        {
            return ANTIFIRE;
        }
        if (normalizedName.startsWith("goading potion"))
        {
            return GOADING_POTION;
        }
        if (normalizedName.startsWith("menaphite remedy"))
        {
            return MENAPHITE_REMEDY;
        }
        if (normalizedName.startsWith("liquid adrenaline"))
        {
            return LIQUID_ADRENALINE;
        }
        if (normalizedName.startsWith("surge potion"))
        {
            return SURGE_POTION;
        }
        if (normalizedName.startsWith("moonlight potion"))
        {
            return MOONLIGHT_POTION;
        }

        switch (normalizedName)
        {
            case "antipoison":
            case "superantipoison":
            case "antidote+":
            case "antidote++":
            case "sanfew serum":
                return ANTIPOISON;

            case "anti-venom":
            case "anti-venom+":
            case "extended anti-venom+":
            case "antivenom":
            case "antivenom+":
            case "extended antivenom+":
                return ANTIVENOM;

            case "imbued heart":
            case "saturated heart":
                return IMBUED_HEART;

            default:
                return null;
        }
    }
}

package com.mason.divinepotiontimer;

import net.runelite.api.Constants;

/** Tracks an active effect countdown and its post-expiration icon state. */
final class PotionTimer
{
    private static final long GAME_TICK_MILLIS = Constants.GAME_TICK_LENGTH;

    private long expiresAtMillis;
    private long inactiveSinceMillis;
    private long durationMillis;
    private int lastRemainingTicks;

    /** Updates this timer from the remaining number of game ticks. */
    void updateFromRemainingTicks(int ticksRemaining, long now)
    {
        if (ticksRemaining > 0)
        {
            if (expiresAtMillis <= now || ticksRemaining > lastRemainingTicks || durationMillis <= 0)
            {
                durationMillis = ticksRemaining * GAME_TICK_MILLIS;
            }

            expiresAtMillis = now + ticksRemaining * GAME_TICK_MILLIS;
            inactiveSinceMillis = expiresAtMillis;
            lastRemainingTicks = ticksRemaining;
        }
        else if (expiresAtMillis > 0)
        {
            markExpired(now);
        }
    }

    /** Updates this timer from a remaining duration in milliseconds. */
    void updateFromDurationMillis(long remainingMillis, long now)
    {
        if (remainingMillis > 0)
        {
            durationMillis = remainingMillis;
            expiresAtMillis = now + remainingMillis;
            inactiveSinceMillis = expiresAtMillis;
            lastRemainingTicks = 0;
        }
        else if (expiresAtMillis > 0)
        {
            markExpired(now);
        }
    }

    private void markExpired(long now)
    {
        expiresAtMillis = 0;
        durationMillis = 0;
        lastRemainingTicks = 0;
        inactiveSinceMillis = now;
    }

    boolean isActive(long now)
    {
        return expiresAtMillis > now;
    }

    int getSecondsRemaining(long now)
    {
        if (!isActive(now))
        {
            return 0;
        }

        return (int) Math.max(1, (expiresAtMillis - now + 999) / 1000);
    }

    double getRemainingFraction(long now)
    {
        if (!isActive(now) || durationMillis <= 0)
        {
            return 0;
        }

        double remainingFraction = (double) (expiresAtMillis - now) / durationMillis;
        return Math.max(0, Math.min(1, remainingFraction));
    }

    boolean isWithinResetDelay(long now, int delaySeconds)
    {
        return !isActive(now)
            && inactiveSinceMillis > 0
            && delaySeconds > 0
            && now < inactiveSinceMillis + delaySeconds * 1000L;
    }
}

package com.mason.divinepotiontimer;

/** Immutable timer values used by the optional visual previews. */
final class TestTimerPreview
{
    private final int secondsRemaining;
    private final double remainingFraction;
    private final boolean venomPhase;

    TestTimerPreview(int secondsRemaining, double remainingFraction, boolean venomPhase)
    {
        this.secondsRemaining = Math.max(0, secondsRemaining);
        this.remainingFraction = Math.max(0, Math.min(1, remainingFraction));
        this.venomPhase = venomPhase;
    }

    int getSecondsRemaining()
    {
        return secondsRemaining;
    }

    double getRemainingFraction()
    {
        return remainingFraction;
    }

    boolean isVenomPhase()
    {
        return venomPhase;
    }
}

